<section class="wrap section"><h1>{{ __('Your shopping bag') }}</h1>@foreach($errors->all() as $error)<p class="error" role="alert">{{ $error }}</p>@endforeach
@if($cart->items->isEmpty())<div class="empty"><h2>{{ __('Your next favourite is waiting') }}</h2><p>{{ __('Add a piece to start your order.') }}</p><a class="button" href="{{ route('catalog') }}">{{ __('Explore the collection') }}</a></div>@else<div class="bag-layout"><div>@foreach($cart->items as $item)<article class="bag-item" wire:key="item-{{ $item->id }}"><img src="{{ $item->variant->product->image() }}" alt="{{ $item->variant->product->name }}" width="120" height="150"><div><h3><a href="{{ route('product',$item->variant->product->slug) }}">{{ $item->variant->product->localized('name') }}</a></h3><p>{{ $item->variant->size }} / {{ $item->variant->color }}</p><p>{{ \App\Support\Money::format($item->variant->price()) }}</p><div class="quantity-control"><button aria-label="{{ __('Decrease quantity') }}" wire:click="setQuantity({{ $item->variant_id }},{{ $item->quantity-1 }})" wire:loading.attr="disabled">−</button><span>{{ $item->quantity }}</span><button aria-label="{{ __('Increase quantity') }}" wire:click="setQuantity({{ $item->variant_id }},{{ $item->quantity+1 }})" wire:loading.attr="disabled">+</button><button class="text-link" wire:click="setQuantity({{ $item->variant_id }},0)" wire:loading.attr="disabled">{{ __('Remove') }}</button></div></div><strong>{{ \App\Support\Money::format($item->quantity*$item->variant->price()) }}</strong></article>@endforeach<span wire:loading role="status">{{ __('Updating your bag…') }}</span></div><aside class="order-summary"><h2>{{ __('Order summary') }}</h2><dl><div><dt>{{ __('Subtotal') }}</dt><dd>{{ \App\Support\Money::format($subtotal) }}</dd></div></dl><p class="muted">{{ __('Shipping and eligible discounts are calculated at checkout.') }}</p><a class="button full" href="{{ route('checkout') }}">{{ __('Continue to checkout') }}</a><a class="text-link" href="{{ route('catalog') }}">{{ __('Continue shopping') }}</a></aside></div>@endif</section>
